    const hits = [];
    const re = /"videoRenderer":\{"videoId":"([\w-]{11})".*?"title":\{"runs":\[\{"text":"(.*?)"\}/g;
    let m, n = 0;
    while ((m = re.exec(t)) && n < 4) { hits.push({ id: m[1], title: m[2].slice(0, 70) }); n++; }
    out[name] = hits;
  } catch (e) { out[name] = String(e); }
}
